public class Solution {
    public static double triangleArea(int a, int b, int c) {
        // Check if given sides form a valid triangle
        if (a + b <= c || a + c <= b || b + c <= a)
            return -1;

        // Compute s, which is the semi-perimeter of the triangle
        double s = (a + b + c) / 2.0;

        // Implement Heron's formula
        double area = Math.sqrt(s * (s - a) * (s - b) * (s - c));

        // Round the area to 2 decimal places and return
        return Math.round(area * 100.0) / 100.0;
    }

    // Test the function
    public static void main(String[] args) {
        System.out.println(triangleArea(3, 4, 5));  // Outputs: 6.0
        System.out.println(triangleArea(1, 2, 10));  // Outputs: -1.0
    }
}

