        for i in range(N):
            for j in range(N):
                dp[i][j][0] = grid[i][j]

        pq = [(grid[0][0], 0, 0, 0)]

        while pq:
            curr_sum, x, y, steps = heapq.heappop(pq)
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < N and 0 <= ny < N:
                    if steps + 1 < k and curr_sum + grid[nx][ny] < dp[nx][ny][steps + 1]:
