def geometric_mean_greaterones(lst):
    # Initialize variables
    n_values = 0
    mult = 1

    # For every number in the list, multiply them together if it's greater than 1
    for num in lst:
        if num > 1:
            mult *= num
            n_values += 1

    # If there are no numbers greater than one, the geometric mean is 0
    if n_values == 0:
