def is_prime(n):
    '''Check if a number is prime. 0, 1, and numbers less than 0 are not prime'''
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def odd_sum_prime_index_elements(x, l):
    '''Given a list of positive integers x and a limit l, return a sorted list that contains all unique elements with an odd sum, an index that is a prime number, and values greater than the limit l.'''

    output = []

    # Iterate over the elements of x
    for i in range(len(x)):
        # The element is not greater than the limit l
        if x[i] <= l:
            continue
        # Sum of digits is not odd
        elif sum(int(num) for num in str(x[i])) % 2 == 0:
            continue
        # Index is not prime
        elif not is_prime(i):
            continue
        # If the element passes all three conditions, append it to output
        else:
            output.append(x[i])

    # Remove duplicates and return a sorted list
    return sorted(list(set(output)))

