def is_palindrome(string: str, l: int, r: int) -> bool:
    if l >= r:
        return True
    if string[l].lower() == string[r].lower():
        return is_palindrome(string, l+1, r-1)
    else:
        return False

def extended_palindromic_sequence(string: str) -> str:
    for i in range(len(string), -1, -1):
        if is_palindrome(string, 0, i-1):
            return string[:i]
    return ''

def make_palindrome(string: str) -> str:
    if len(string) > 200:
        raise ValueError("The input string exceeds 200 characters")
    string = ''.join(ch for ch in string if ch.isalnum())
    sequence = extended_palindromic_sequence(string)
    return string + string[:len(string)-len(sequence)][::-1]

