import java.util.*;

class Solution {
    static Map<Integer, Integer> cache = new HashMap<>();

    public static int trifib(int n) {
        if (n == 0) {
            return 0;
        }
        if (n == 1) {
            return 0;
        }
        if (n == 2) {
            return 1;
        }
        if (cache.containsKey(n)) {
            return cache.get(n);
        }

        int res = trifib(n - 1) + trifib(n - 2) + 2 * trifib(n - 3);
        cache.put(n, res);
        return res;
    }

    public static void main(String args[]) {
        int n = 20; // Element of the sequence to compute
        long startTime = System.currentTimeMillis();
        int result = trifib(n);
        long endTime = System.currentTimeMillis();

        System.out.println("The " + n + "th number in the tri-fibonacci sequence is: " + result);
        System.out.println("Computation time: " + (endTime - startTime) + "ms");
    }
}

