import re

def parse_string(str):
    count = {
        'upper': 0,
        'lower': 0,
        'digits': 0,
        'non_alpha': 0
    }

    regex_word = re.compile(r'\b\w+\b')

    # If the string is alphabetic and uppercase...
    if str.isalpha() and str.isupper():
        # Return the sum of ASCII values (mod 26) for all characters
        return sum((ord(c) - 65) % 26 for c in str)

    # If the string contains non-digit, non-alphabetic characters...
    elif re.search(r'\W', str):
        words = regex_word.findall(str)

        # Update the count of character types
        count['upper'] += sum(1 for c in str if c.isupper())
        count['lower'] += sum(1 for c in str if c.islower())
        count['digits'] += sum(1 for c in str if c.isdigit())
        count['non_alpha'] += sum(1 for c in str if not c.isalnum())

        # Check for words with consecutive duplicate characters
        freq = {word: len(re.findall(r'(.)\1', word)) for word in words if re.search(r'(.)\1', word)}

        if freq: return freq
        else: return count

    # Otherwise, for values separated by common delimiters...
