import java.util.*;
import java.lang.*;

class Solution {
    public List<List<String>> listSort(List<String> lst) {
        // Deleting strings of odd lengths
        lst.removeIf(s -> s.length() % 2 != 0);

        // Sorting the list of strings first by their lengths and then alphabetically
        lst.sort(Comparator.comparing(String::length).thenComparing(String::compareTo));

        // Using LinkedHashMap to maintain the order of insertion
        Map<Integer, List<String>> map = new LinkedHashMap<>();

        for (String s : lst) {
            // Grouping the strings by their lengths and eliminating duplicates
            map.putIfAbsent(s.length(), new ArrayList<>());
            if (!map.get(s.length()).contains(s))
                map.get(s.length()).add(s);
        }

        // Returning the list of grouped strings
        return new ArrayList<>(map.values());
    }
}

