import collections
from typing import List
# Find all distinct balanced bracket sequences of given length:
def balanced_bracket_sequences(n: int) -> int:
    if n % 2 != 0:
        return 0

    dp = [0 for _ in range(n+1)]
    dp[0] = 1

    for i in range(2, n+1, 2):
        for j in range(0, i-1, 2):
            dp[i] += dp[j] * dp[i-2-j]

    return dp[n]

# Count unique subsequences of a specified substring in the main string, using Trie data structure:
def unique_subsequences(string: str, substring: str) -> int:
    dp = [0] * (len(string)+1)
    dp[0] = 1
    last_occurrence = collections.defaultdict(int)

    for i, char in enumerate(string, start=1):
        dp[i] = 2 * dp[i-1]
        if char in last_occurrence:
            dp[i] -= dp[last_occurrence[char] - 1]
        last_occurrence[char] = i

    return dp[-1] - 1 - any(unique_subsequences(string[i+1:], substring) for i, char in enumerate(string) if char == substring[0])

