        substrings = []
        for i in range(len(string)):
            for j in range(i, len(string)):
                prime_freq = True
                for k, v in collections.Counter(string[i:j+1]).items():
                    if not is_prime(v):
                        prime_freq = False
                        break
                if prime_freq:
                    substrings.append(string[i:j+1])
        return substrings

