import java.util.*;
import java.lang.*;

class Solution {

    public static Pair<String, List<Integer>> swapOdd(List<Integer> lst1, List<Integer> lst2, int n) {
        PriorityQueue<Pair<Integer, Integer>> heap
                = new PriorityQueue<>(Comparator.comparing((Pair<Integer, Integer> p) -> p.getValue()).reversed());
        Map<Integer, Integer> map = new HashMap<>();
        List<Integer> evenList = new ArrayList<>();
        int oddInFirst = 0;

        for (int num : lst2) {
            if (num % 2 == 0) {
                evenList.add(num);
            } else {
                map.put(num, map.getOrDefault(num, 0) + 1);
            }
        }

        for (int num : lst1) {
            if (num % 2 != 0) {
                oddInFirst++;
            }
        }

        if (oddInFirst < evenList.size()) {
            return new Pair<>("Failure", new ArrayList<>());
        }

        for (Map.Entry<Integer, Integer> entry : map.entrySet()) {
            heap.add(new Pair<>(entry.getKey(), entry.getValue()));
        }

        List<Integer> result = new ArrayList<>();
        while (n-- > 0 && !heap.isEmpty()) {
            result.add(heap.poll().getKey());
        }
        return new Pair<>("Success", result);
    }

    public static void main(String[] args) {
        Pair<String, List<Integer>> result = Solution.swapOdd(Arrays.asList(1, 2, 3, 4), Arrays.asList(1, 2, 3, 4), 2);
        System.out.println(result.getKey() + " " + result.getValue());

        result = Solution.swapOdd(Arrays.asList(1, 2, 3, 4), Arrays.asList(1, 6, 3, 4), 3);
        System.out.println(result.getKey() + " " + result.getValue());
    }
}

