class Solution {
    public boolean isHappy(String s) {
        if (s.length() < 3) {
            return false; // less than three letters
        }

        String firstSequence = s.substring(0, 3);

        if (!areAllCharsUnique(firstSequence)) {
            return false; // first three letters are not distinct
        }

        if (s.length() % 3 != 0) {
            return false; // length not multiple of 3, cannot be happy
        }

        for (int i = 3; i < s.length(); i += 3) {
            String sequence = s.substring(i, i + 3);
            if (!areAllCharsUnique(sequence) || !sequence.equals(firstSequence)) {
                return false; // a sequence has same letter or different sequence
            }
