const overlapAndFactorial = (interval1, interval2) => {
    // Find the overlap
    const start = Math.max(interval1[0], interval2[0]);
    const end = Math.min(interval1[1], interval2[1]);

    // If there is no overlap
    if (start > end) {
        return -1;
    }

    // Calculate the length of the overlap
    const length = end - start;

    // Calculate the factorial of the length
    let factorial = 1;
    for(let i = 2; i <= length; i++) {
        factorial *= i;
    }

