import heapq

def complex_median(lst):
    max_heap = [] # The largest element is at the front.
    min_heap = [] # The smallest element is at the front.

    def add_number(num, min_heap, max_heap):
        if len(max_heap) == 0 or num < -max_heap[0]:
            heapq.heappush(max_heap, -num)
        else:
            heapq.heappush(min_heap, num)

    def rebalance(min_heap, max_heap):
        if len(max_heap) < len(min_heap):
            number = heapq.heappop(min_heap)
            heapq.heappush(max_heap, -number)
        elif len(max_heap) > len(min_heap) + 1:
            number = -heapq.heappop(max_heap)
            heapq.heappush(min_heap, number)

    def get_median(min_heap, max_heap):
        if len(max_heap) > len(min_heap):
            return float(-max_heap[0])
        else:
            return (min_heap[0] - max_heap[0]) / 2.0

    for num in lst:
        add_number(num, min_heap, max_heap)
        rebalance(min_heap, max_heap)

    return get_median(min_heap, max_heap)

