    paren_string = paren_string.replace(' ', '')

    paren_groups = []
    open_count = close_count = 0
    last_bracket_was_open = False
    group_start = 0

    for i, c in enumerate(paren_string):
        print(f"Processing character {i}: {c}")

        if c == '(':
            open_count += 1
            last_bracket_was_open = True
        elif c == ')':
            close_count += 1
            last_bracket_was_open = False

        if i == len(paren_string)-1 or (not last_bracket_was_open and paren_string[i+1] == '('):
            if close_count == open_count:
                print(f"Found balanced group at index {group_start}-{i}")
