        return lst[0]

    pivot = lst[len(lst) // 2]
    low = [j for j in lst if j < pivot]
    high = [j for j in lst if j > pivot]

    k = len(low)
    if i < k:
        return hoare_select(low, i)
    elif i > k:
        return hoare_select(high, i - k - 1)
    else: 
        return pivot

