#include <string>
#include <vector>
using namespace std;

vector<int> computeTemporaryArray(string pattern)
{
    vector<int> lps(pattern.length());
    int index = 0;
    for (int i = 1; i < pattern.length();)
    {
        if (pattern[i] == pattern[index])
        {
            lps[i] = index + 1;
            index++;
            i++;
        }
        else
        {
            if (index != 0) index = lps[index - 1];
            else
            {
                lps[i] = 0;
                i++;
            }
        }
    }
    return lps;
}

int KMP(string text, string pattern)
{
    vector<int> lps = computeTemporaryArray(pattern);
    int i = 0;
    int j = 0;
    int len = text.length();
    while (i < len && j < pattern.length())
    {
        if (text[i] == pattern[j])
        {
            i++;
            j++;
        }
        else
        {
            if (j != 0)
                j = lps[j - 1];
            else
                i++;
        }
    }
    if (j == pattern.length())
        return 1;
    return j;
}

string make_palindrome(string str)
{
    string rev = string(str.rbegin(), str.rend());
    string combined = str + "#" + rev;
    int len = combined.length();

    int pref_len = KMP(combined, rev);

    string add = str.substr(pref_len);
    reverse(add.begin(), add.end());

    return str + add;
}
