def correctBracketing(s: str) -> bool:
    # Storing the opening brackets
    opening = ['(', '[']

    # Storing the closing brackets
    closing = [')', ']']

    # Using a list as a Stack
    stack = []

    for symbol in s:
        if symbol in opening:
            # Push to stack if it's an opening bracket
            stack.append(symbol)
        elif symbol in closing:
            # If stack is empty, brackets are not balanced
            if not stack:
                return False
            else:
                # Pop the opening bracket from stack
                open_bracket = stack.pop()

                # Check if the popped opening bracket matches with the closing bracket
                if open_bracket == '(' and symbol != ')':
                    return False
                if open_bracket == '[' and symbol != ']':
                    return False

    # If stack is not empty at the end, brackets are not balanced
    if stack:
        return False

    return True
