func SortThird(l []int) []int {
    // Create an auxiliary slice to hold the elements at indices divisible by 3 
    var aux []int 
    for i := 0; i < len(l); i += 3 {
        aux = append(aux, l[i])
    }

    // Sort the auxiliary slice in increasing order
    sort.Ints(aux)

    // Replace the elements in the original slice at indices divisible by 3 with the sorted elements
    for i, j := 0, 0; i < len(l); i += 3 {
        l[i] = aux[j]
        j++
    }
    return l
}

