string circular_shift(int x, int shift) {
    // Ensure that 'x' is non-negative.
    if (x < 0) {
        throw invalid_argument("Input 'x' must be non-negative");
    }

    // Ensure that 'shift' is valid.
    if (abs(shift) > 32) {
        throw invalid_argument("Shift amount must be between -32 and 32");
    }

    unsigned int unsigned_x = static_cast<unsigned int>(x);
    int bin_length = 32; // For 32-bit integers

    // Handle 'shift' larger than binary length.
    shift %= bin_length;

    if (shift < 0) {
        // Left rotation
        shift = abs(shift);   
        return bitset<32>((unsigned_x << shift) | (unsigned_x >> (bin_length - shift))).to_string();
    } else {
        // Right rotation
        return bitset<32>((unsigned_x >> shift) | (unsigned_x << (bin_length - shift))).to_string();
    }
}

