def separate_paren_groups(paren_string: str) -> List[str]:
    groups = {i: [] for i in range(len(paren_string))}
    stack = []
    balances = {')': '(', ']': '[', '}': '{'}
    for char in paren_string:
        if char.strip():
            if char in balances.values():
                stack.append(len(stack))
            elif len(stack) > 0 and balances[char] == groups[stack[-1]][-1]:
                index = stack.pop()
                groups[index].append(char)
                if len(stack) > 0:
                    groups[stack[-1]] += groups[index]
                    del groups[index]
            else:
                return []
    return [''.join(groups[i]) for i in range(len(stack))]

