def modify_string(string: str) -> str:
    new_string = ''
    set_char = set()
    for char in string:
        if char.isalpha():
            if char.lower() in ['a', 'e', 'i', 'o', 'u']:
                new_string += str(ord(char))
            else:
                new_string += char.lower() if char.isupper() else char.upper()
        elif char.isdigit():
            digit = int(char)
            if digit % 2 != 0:
                new_string += str(digit + 1)
            else:
                new_string += char
        else:
            if char not in set_char:  
                new_string += char * 2  
            else:
                new_string += char  
            set_char.add(char)  

    special_chars = [char for char in new_string if not char.isalnum()]
    special_chars.sort(key=lambda x: ord(x))

    for special_char in set_char:
        new_string = new_string.replace(special_char*2, special_char)
        new_string = new_string.replace(special_char, '')

