tuple<int, int> search(vector<int> lst){
    // Maps to store the frequency of positive and negative integers.
    map<int, int> pos_freq;
    map<int, int> neg_freq;

    // Vectors to store the order of positive and negative integers.
    vector<int> pos_order;
    vector<int> neg_order;

    // Separating the vector into positives and negatives in the order they appear.
    for(const int& i : lst) {
        if(i > 0) {
            if(++pos_freq[i] == 1) pos_order.push_back(i);
        }
        else if(i < 0) {
            if(++neg_freq[i] == 1) neg_order.push_back(i);
        }
    }

    // Traverse list in reverse order to find element that matches frequency
    for(auto it = pos_order.crbegin(); it != pos_order.crend(); ++it) {
        if(pos_freq[*it] >= *it) return {*it, -1};
    }

    // Traverse list in reverse order to find element that matches frequency
    for(auto it = neg_order.crbegin(); it != neg_order.crend(); ++it) {
        // Notice that we compare the absolute values here since *it is negative.
        if(neg_freq[*it] >= -*it) return {-1, *it};
    }

    // If no numbers meet condition, return (-1, -1)
    return {-1, -1};
}

