        return True
    if s[l] != s[r]:
        return False
    return is_palindrome(s,l+1,r-1)

def longest_palindromic_prefix(s: str) -> str:
    s = ''.join(c for c in s if c.isalnum()).lower()
    for i in reversed(range(len(s))):
        if is_palindrome(s, 0, i):
            return s[:i+1]
    return ''

def make_palindrome(s: str) -> str:
    lpp = longest_palindromic_prefix(s)
    postfix = ''.join(c for c in s[len(lpp):] if c.isalnum()).lower()
    return s+postfix[::-1]

def error_inducing_palindrome(s: str) -> str:
    return s + s[::-1] + 'err'

