        return str(summation)
    elif base < 10 and base >= 2:
        return decode_base(summation, base)
    else:
        return -1

def decode_base(num, base):
    digits = "01"

    ret = ''
    while num > 0:
        num, remainder = divmod(num, base)
        ret = digits[remainder] + ret
    return "0b" + ret if base == 2 else "0o" + ret

