class AdvancedSolution {
    /**
    Test if the given string is a palindrome considering only alphanumeric characters. Ignore case differences.
    For example, "A man, a plan, a canal: Panama" is a palindrome.
     */
    public boolean isPalindrome(String s) {
        s = s.replaceAll("\\W", "").toLowerCase();
        int start = 0;
        int end = s.length()-1;
        while (start < end) {
            if (s.charAt(start) != s.charAt(end)) {
                return false;
            }
            start +=1;
            end -=1;
        }
        return true;
    }

    /*
    Find the shortest palindrome that begins with the supplied string by adding its missing parts at the ends or in between. 
    Also consider multiple possible palindromes and select the lexicographically smallest option.
    For example, given string "cat", possible palindromes can be "catac", "atcata" etc., choose the lexicographically smallest which is "atcata".
    */
    public String formShortestPossiblePalindrome(String s) {
        if (s == null || s.length() == 0) {
            return s;
        }

        String rev_s = new StringBuilder(s).reverse().toString();
        String l = s + "#" + rev_s;

        int[] p = new int[l.length()];

        for (int i = 1; i < l.length(); i++) {
            int j = p[i - 1];
            while (j > 0 && l.charAt(i) != l.charAt(j)) {
                j = p[j - 1];
            }
            if (l.charAt(i) == l.charAt(j)) {
                p[i] = j + 1;
            }
        }

        String add = s.substring(p[p.length - 1]);
        String add_rev = new StringBuilder(add).reverse().toString();

        return add_rev + s;
    }
}

