import java.util.*;

class Solution {
    public int adjustDigitSum(String s, int cutOff) {
        int sumUpper = 0, sumLower = 0;

        for (char c: s.toCharArray()) {
            if (Character.isUpperCase(c)) {
                sumUpper += (int) c;
            } else if (Character.isLowerCase(c)) {
                sumLower += (int) c;
            }
        }

        if (sumUpper < cutOff) {
            sumUpper = 0;
        }

        int overallSum = sumUpper - sumLower;

        return overallSum < 0 ? 0 : overallSum;
    }
