def descriptive_stats(l: list):
    l.sort()
    length = len(l)

    # Computing Median
    if length % 2 != 0:
        median = l[length // 2]
    else:
        median = (l[length // 2 - 1] + l[length // 2]) / 2

    # Computing Mode
    count_dict = {}
    for i in l:
        if i in count_dict:
            count_dict[i] += 1
        else:
            count_dict[i] = 1
    max_freq = max(count_dict.values())
    mode = [k for k, v in count_dict.items() if v == max_freq] 
    mode = mode[0] if len(mode) == 1 else None  # if multiple items have the same frequency

    # Computing Range
    range_ = max(l) - min(l)

    # Computing Interquartile Range
    if length % 2 != 0:
        q1 = l[length // 4]
        q3 = l[3 * length // 4]
    else:
        q1 = (l[length // 4 - 1] + l[length // 4]) / 2
        q3 = (l[3 * length // 4 - 1] + l[3 * length // 4]) / 2
    iqr = q3 - q1

    return {'Median': median, 'Mode': mode, 'Range': range_, 'Interquartile Range': iqr}
