class Solution {
    public Optional<String> secondLongest(String[] arr) {
        if (arr.length < 2) {
            return Optional.empty();
        }

        // Sort the array in descending order of length and then lexicographically
        Arrays.sort(arr, new Comparator<String>() {
            public int compare(String s1, String s2) {
                if (s1.length() != s2.length()) {
                    return s2.length() - s1.length();
                } else {
                    return s1.compareTo(s2);
                }
            }
        });

        String longestString = arr[0];
        for (int i = 1; i < arr.length; i++) {
            // Skip the strings that have the same length as the longest string
            if (arr[i].length() == longestString.length()) {
                continue;
            }
            // Find the second longest string that has a different length from the longest string
            return Optional.of(arr[i]);
        }
        return Optional.empty();
    }
}

