from typing import List, Tuple, Union
from threading import Lock

class Account:
    _lock = Lock()

    def __init__(self, account_number: int):
        self.account_number = account_number
        self.balance = 0

    def deposit(self, amount: int):
        with self._lock:
            if amount <= 0:
                raise ValueError("Deposit amount must be positive.")
            self.balance += amount

    def withdraw(self, amount: int):
        with self._lock:
            if amount > self.balance:
                raise ValueError("Withdraw amount exceeds balance.")
            self.balance -= amount

def account_transactions(accounts_transactions: List[Tuple[int, str, int]]) -> Union[bool, List[Tuple[str, int]]]:
    """
    Function accepts a list of account numbers and corresponding banking operations, returning True if any account's balance falls 
    below zero. If all accounts stay in combination, it returns False. The function also returns an error message and the
    index(s) of the faulty operation(s) when encountering invalid account numbers, negative deposits, or withdrawal exceeding present balance.

    The input list contains tuples in the format (Account_number, Operation_type, Operation_value).

    >>> account_transactions([(1, 'Deposit', 1), (2, 'Deposit', 2), (1, 'Deposit', 3), (2, 'Withdrawal', 4)])
    False
    >>> account_transactions([(1, 'Deposit', 5), (1, 'Withdrawal', 6), (1, 'Deposit', 1), (1, 'Withdrawal', 2)])
    True, [('Withdraw amount exceeds balance.', 1)]
    >>> account_transactions([(3, 'Deposit', -10), (4, 'Deposit', -5)])
    True, [('Deposit amount must be positive.', 0), ('Deposit amount must be positive.', 1)]
    """

    accounts = {}
    erroneous_transactions = []

    for i, transaction in enumerate(accounts_transactions):
        account_number, operation_type, operation_value = transaction

        if account_number not in accounts:
            accounts[account_number] = Account(account_number)

        try:
            if operation_type == 'Deposit':
                accounts[account_number].deposit(operation_value)
            elif operation_type == 'Withdrawal':
                accounts[account_number].withdraw(operation_value)
            else:
                erroneous_transactions.append(('Invalid operation type.', i))

