class Solution {
    String maxWord = "";
    int maxCount = 0;

    public String findMax(List<String> words) {
        binarySearch(words, 0, words.size() - 1);
        return maxWord;
    }

    private void binarySearch(List<String> words, int start, int end) {
        if(start <= end) {
            int mid = start + (end - start) / 2;
            String word = words.get(mid);
            int count = (int) word.chars()
                .distinct()
                .count();

            if(count > maxCount) {
                maxCount = count;
                maxWord = word;
            }
            else if(count == maxCount && words.indexOf(word) < words.indexOf(maxWord)) {
                maxWord = word;
            }

            binarySearch(words, start, mid - 1);
            binarySearch(words, mid + 1, end);
        }
    }
}

