def partition(l, low, high):
    pivot = l[high]
    i = low - 1
    for j in range(low, high):
        if l[j] <= pivot:
            i += 1
            l[i], l[j] = l[j], l[i]
    l[i+1], l[high] = l[high], l[i+1]
    return i + 1

def quickSelect(l, low, high, k):
    if low == high:
        return l[low]

    pivotIndex = partition(l, low, high)

    if k == pivotIndex:
        return l[k]
    elif k < pivotIndex:
        return quickSelect(l, low, pivotIndex - 1, k)
    else:
        return quickSelect(l, pivotIndex + 1, high, k)    

def median(l: list):
    """Return median of elements in the list l without sorting it or using built-in functions.
    Handles tuples with even and odd number of elements, and duplicates.
    >>> median([3, 1, 2, 4, 5])
    3
    >>> median([-10, 4, 6, 1000, 10, 20])
    15.0
    >>> median([1, 2, 2, 4, 5])
    2
    """
    length = len(l)
    if length % 2 == 0:
        return (quickSelect(l, 0, length - 1, length // 2 - 1) + quickSelect(l, 0, length - 1, length // 2)) / 2
    else:
        return quickSelect(l, 0, length - 1, length // 2)

