def is_palindrome(string: str) -> bool:
    """ Examine if a particular string is a palindrome """
    length = len(string)
    for i in range(length // 2):
        if string[i] != string[length - i - 1]:
            return False
    return True

def make_palindrome(string: str) -> str:
    """ Construct the shortest palindrome starting with a particular string """
    length = len(string)
    for i in range(length):
        if is_palindrome(string[i:]):
            return string + string[:i][::-1]
    return string + string[::-1]

def find_palindromes(string: str) -> list:
    """ Discover all palindromic substrings in a specific string in ascending order by their lengths """
    palindromes = set()
    length = len(string)
    for i in range(length):
        for j in range(i+1, length+1):
            substring = string[i:j]
            if is_palindrome(substring):
                palindromes.add(substring)
    return sorted(list(palindromes), key=len)

